<x-layouts.app title="Master Shift" active="shifts" :current-client="$currentClient" :user="$user">
<div class="mb-6 flex items-end justify-between"><div><p class="text-xs text-slate-500">Master Data / Shift</p><h1 class="mt-2 text-2xl font-semibold text-slate-950">Master Shift</h1><p class="mt-1 text-sm text-slate-500">Atur jadwal kerja operasional client.</p></div><button type="button" data-shift-create class="inline-flex h-11 items-center gap-2 rounded-lg bg-primary-600 px-4 text-sm font-semibold text-white"><x-icon name="plus" size="size-4"/> Tambah shift</button></div>
<x-card :padding="false"><table data-server-table class="w-full text-left text-sm"><thead><tr><th>Kode</th><th>Nama shift</th><th>Mulai</th><th>Selesai</th><th>Status</th><th>Aksi</th></tr></thead><tbody></tbody></table></x-card>
<div data-shift-modal class="fixed inset-0 z-[90] hidden place-items-center bg-slate-950/40 p-4"><div class="w-full max-w-lg rounded-xl bg-white p-6 shadow-xl"><div class="mb-5 flex items-center justify-between"><h2 data-shift-modal-title class="text-lg font-semibold">Tambah shift</h2><button type="button" data-shift-close aria-label="Tutup"><x-icon name="x-mark"/></button></div><form data-shift-form class="grid gap-4"><input type="hidden" name="_method" value="POST"><div class="grid gap-4 sm:grid-cols-2"><label class="grid gap-2 text-sm font-semibold"><span>Kode <span class="text-danger">*</span></span><input name="code" required placeholder="Contoh: PAGI" class="h-11 rounded-lg border border-line px-3 font-normal"></label><label class="grid gap-2 text-sm font-semibold"><span>Nama <span class="text-danger">*</span></span><input name="name" required placeholder="Contoh: Shift Pagi" class="h-11 rounded-lg border border-line px-3 font-normal"></label><label class="grid gap-2 text-sm font-semibold"><span>Jam mulai <span class="text-danger">*</span></span><input type="time" name="start_time" required class="h-11 rounded-lg border border-line px-3 font-normal"></label><label class="grid gap-2 text-sm font-semibold"><span>Jam selesai <span class="text-danger">*</span></span><input type="time" name="end_time" required class="h-11 rounded-lg border border-line px-3 font-normal"></label></div><label class="grid gap-2 text-sm font-semibold"><span>Status <span class="text-danger">*</span></span><select name="status" required class="h-11 rounded-lg border border-line bg-white px-3 font-normal"><option value="active">Aktif</option><option value="inactive">Nonaktif</option></select></label><div class="flex justify-end gap-3"><button type="button" data-shift-close class="rounded-lg border border-line px-4 py-2.5 text-sm font-semibold">Batal</button><button class="rounded-lg bg-primary-600 px-4 py-2.5 text-sm font-semibold text-white">Simpan</button></div></form></div></div>
